const raw = String($json.message_text || '').trim();
const match = raw.match(/https?:\/\/[^\s]+/i);
if (!match) return [];
const url = new URL(match[0]);
const tracking = /^(utm_|fbclid$|gclid$|mc_cid$|mc_eid$|ref$|source$)/i;
[...url.searchParams.keys()].forEach((key) => { if (tracking.test(key)) url.searchParams.delete(key); });
url.hash = ''; url.hostname = url.hostname.toLowerCase();
if (url.pathname !== '/') url.pathname = url.pathname.replace(/\/+$/, '');
const canonical_url = url.toString();
let hash = 2166136261; for (const char of canonical_url) { hash ^= char.charCodeAt(0); hash = Math.imul(hash, 16777619); }
const content_key = 'ck_' + (hash >>> 0).toString(36);
return [{ json: { ...$json, message_text: canonical_url, article_url: canonical_url, content_key } }];

const raw_output = String($json.output || $json.pack_json || '');
let pack = {}; const errors = [];
try { pack = JSON.parse(raw_output.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '')); } catch { errors.push('Output is not valid JSON'); }
const required = ['article_url','chat_id','content_key','linkedin_post','x_post_1','x_post_2','x_post_3','newsletter_blurb','hook','pull_quote'];
for (const key of required) if (pack[key] === undefined || pack[key] === null || String(pack[key]).trim() === '') errors.push('Missing ' + key);
const words = (v) => String(v || '').trim().split(/\s+/).filter(Boolean).length;
if (words(pack.linkedin_post) > 150) errors.push('LinkedIn post exceeds 150 words');
for (const key of ['x_post_1','x_post_2','x_post_3']) if (String(pack[key] || '').length > 280) errors.push(key + ' exceeds 280 characters');
if (words(pack.hook) > 15) errors.push('Hook exceeds 15 words');
if (String(pack.newsletter_blurb || '').split(/[.!?]+/).filter(s=>s.trim()).length < 2) errors.push('Newsletter blurb needs two sentences');
return [{json:{...$json, raw_output, pack_json: JSON.stringify(pack), quality_passed: errors.length === 0, quality_errors: errors.join('; ')}}];

