const since = Date.now() - 7 * 24 * 60 * 60 * 1000;
const metrics = { packs: 0, failures: 0, approvals: 0, deliveries: 0, per_day: {}, per_channel: { linkedin: 0, x: 0, newsletter: 0 } };
const day = (value) => new Date(value).toISOString().slice(0,10);
for (const {json} of items) {
  if (json.reason && Date.parse(json.logged_at || 0) >= since) { metrics.failures++; const d=day(json.logged_at); metrics.per_day[d] ??={packs:0,failures:0,approvals:0,deliveries:0}; metrics.per_day[d].failures++; continue; }
  if (Date.parse(json.packed_at || 0) >= since) { metrics.packs++; const d=day(json.packed_at); metrics.per_day[d] ??={packs:0,failures:0,approvals:0,deliveries:0}; metrics.per_day[d].packs++; metrics.per_channel.linkedin++; metrics.per_channel.x += 3; metrics.per_channel.newsletter++; }
  if (json.status === 'approved' && Date.parse(json.scheduled_at || 0) >= since) metrics.approvals++;
  if (json.status === 'delivered' && Date.parse(json.delivered_at || 0) >= since) { metrics.deliveries++; const d=day(json.delivered_at); metrics.per_day[d] ??={packs:0,failures:0,approvals:0,deliveries:0}; metrics.per_day[d].deliveries++; }
}
return [{json:{metrics,digest_input:JSON.stringify(metrics)}}];
